"""This file contains the Sim Dialogs Kv Generator, Kv Panel Lat Pos, Kv Panel Long Pos Page Object class for the
SIM KV GENERATOR, SIM KV PANEL LAT POS and SIM KV PANEL LONG POS panes in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogKvGeneratorFuncs
from .. interactions import SimDialogKvLatFuncs
from .. interactions import SimDialogKvLongFuncs
from typing import Dict


logger = logging.getLogger(__name__)

class SimDialogsKvPanes(SimDialogs):
    ''' Page Object class for the SIM KV GENERATOR, SIM KV PANEL LAT POS and SIM KV PANEL LONG POS panes'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    #-------------------------------------- SIM KV GENERATOR Pane --------------------------------------

    def toggle_sim_kv_generator_hand_switch_preparatory_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Hand Switch Preparatory checkbox in the Sim kV Generator Pane to
        either checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_hand_switch_preparatory_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_hand_switch_preparatory_checkbox()

    def toggle_sim_kv_generator_hand_switch_exposure_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Hand Switch Exposure checkbox in the Sim kV Generator Pane to
        either checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_hand_switch_exposure_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_hand_switch_exposure_checkbox()

    def toggle_sim_kv_generator_foot_switch_exposure_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Foot Switch Exposure checkbox in the Sim kV Generator Pane to
        either checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_foot_switch_exposure_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_foot_switch_exposure_checkbox()

    def toggle_sim_kv_generator_door_open_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Door Open checkbox in the Sim kV Generator Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_door_open_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_door_open_checkbox()

    def toggle_sim_kv_generator_error_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Error checkbox in the Sim kV Generator Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_error_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_error_checkbox()

    def toggle_sim_kv_generator_enabled_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Enabled checkbox in the Sim kV Generator Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvGeneratorFuncs.check_sim_kv_generator_enabled_checkbox()
        else:
            SimDialogKvGeneratorFuncs.uncheck_sim_kv_generator_enabled_checkbox()

    def set_sim_kv_generator_setting_values(self, setting_type_value_pairs: Dict[str, str]) -> None:
        '''
        Modifies one or more setting fields as specified in the dictionary arg of setting type
        field key: set value pairs in the Sim KV Generator Pane

        Args:
            setting_type_value_pairs (dict of str: str): Dictionary of setting type field
            name to set string as the key, and string value to set as the value.

            Setting type field Keys can be one of the following strings:
            "kV", "mA" or "ms"

            Value can be a numeric value as a string
        '''
        for key, value in setting_type_value_pairs.items():
            if key.casefold() == "kV".casefold():
                SimDialogKvGeneratorFuncs.edit_sim_kv_generator_settings_kv_textfield(value)
            elif key.casefold() == "mA".casefold():
                SimDialogKvGeneratorFuncs.edit_sim_kv_generator_settings_ma_textfield(value)
            elif key.casefold() == "ms".casefold():
                SimDialogKvGeneratorFuncs.edit_sim_kv_generator_settings_ms_textfield(value)
            else:
                logger.info(f"Invalid Sim KV Generator setting: {key}, unable to set")

    #-------------------------------------- SIM KV PANEL LAT POS Pane --------------------------------------

    def toggle_sim_kv_panel_lat_pos_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim kV Panel Lat Pos Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvLatFuncs.check_sim_kv_panel_lat_pos_node_online_checkbox()
        else:
            SimDialogKvLatFuncs.uncheck_sim_kv_panel_lat_pos_node_online_checkbox()

    def toggle_sim_kv_panel_lat_pos_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Auto checkbox in the Sim kV Panel Lat Pos Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvLatFuncs.check_sim_kv_panel_lat_pos_auto_checkbox()
        else:
            SimDialogKvLatFuncs.uncheck_sim_kv_panel_lat_pos_auto_checkbox()

    def read_sim_kv_panel_lateral_position_field(self) -> str:
        '''Gets the kv lateral position field value and returns it if found.

        Returns:
            str or None: Sim KV lateral position value'''
        return SimDialogKvLatFuncs.get_sim_kv_panel_lateral_position_textfield()

    def select_sim_kv_panel_lat_pos_option(self, radio_btn_option: str):
        '''
        Select one of the radio button options for the Sim KV Panel Lat
        Pos pane for the given radio button string

        Args:
            radio_btn_option (str): Name of radio button string to set

            radio_btn_option can be one of the following strings:
            "Illegal", "Small", "Medium" or "Large"
        '''
        if radio_btn_option.casefold() == "Illegal".casefold():
            SimDialogKvLatFuncs.click_sim_kv_panel_lat_pos_illegal_radio_button()
        elif radio_btn_option.casefold() == "Small".casefold():
            SimDialogKvLatFuncs.click_sim_kv_panel_lat_pos_small_radio_button()
        elif radio_btn_option.casefold() == "Medium".casefold():
            SimDialogKvLatFuncs.click_sim_kv_panel_lat_pos_medium_radio_button()
        elif radio_btn_option.casefold() == "Large".casefold():
            SimDialogKvLatFuncs.click_sim_kv_panel_lat_pos_large_radio_button()
        else:
            logger.info(f"Invalid Sim KV Panel Lat Pos radio button option: {radio_btn_option}, unable to set")

    #-------------------------------------- SIM KV PANEL LONG POS Pane --------------------------------------

    def toggle_sim_kv_panel_long_pos_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim kV Panel Long Pos Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvLongFuncs.check_sim_kv_panel_long_pos_node_online_checkbox()
        else:
            SimDialogKvLongFuncs.uncheck_sim_kv_panel_long_pos_node_online_checkbox()

    def toggle_sim_kv_panel_long_pos_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Auto checkbox in the Sim kV Panel Long Pos Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogKvLongFuncs.check_sim_kv_panel_long_pos_auto_checkbox()
        else:
            SimDialogKvLongFuncs.uncheck_sim_kv_panel_long_pos_auto_checkbox()

    def read_sim_kv_panel_longitudinal_position_field(self) -> str:
        '''Gets the kv longitudinal position field value and returns it if found.

        Returns:
            str or None: Sim KV longitudinal position value'''
        return SimDialogKvLongFuncs.get_sim_kv_panel_longitudinal_position_textfield()

    def select_sim_kv_panel_long_pos_option(self, radio_btn_option: str):
        '''
        Select one of the radio button options for the Sim KV Panel Long pane
        for the given radio button string

        Args:
            radio_btn_option (str): Name of radio button string to set

            radio_btn_option can be one of the following strings:
            "Illegal" or "Extended"
        '''
        if radio_btn_option.casefold() == "Illegal".casefold():
            SimDialogKvLongFuncs.click_sim_kv_panel_long_pos_illegal_radio_button()
        elif radio_btn_option.casefold() == "Extended".casefold():
            SimDialogKvLongFuncs.click_sim_kv_panel_long_pos_extended_radio_button()
        else:
            logger.info(f"Invalid Sim KV Panel Long Pos radio button option: {radio_btn_option}, unable to set")